import React, { useRef, useState, useEffect, useCallback } from 'react';
import { Play, Pause, Volume2 } from 'lucide-react';

/**
 * AudioPlayer — reliable audio playback for AI responses
 *
 * ROOT CAUSE of previous silence:
 *   1. useEffect had [base64wav] dep but closed over stale `autoplayed` boolean
 *      → autoplay was attempted once, failed (browser policy), never retried
 *   2. new Audio().play() in ChatPage is a fire-and-forget with no user gesture
 *      → browsers require a user gesture before playing audio
 *
 * FIX:
 *   - Always render a visible PLAY BUTTON — this IS the user gesture
 *   - Attempt autoplay once after a small delay (post-gesture from typing/sending)
 *   - The button is always clickable regardless of autoplay outcome
 *   - Audio object is created fresh on each new base64wav to avoid stale refs
 */
export default function AudioPlayer({ base64wav, autoPlay = true }) {
  const audioRef = useRef(null);
  const [playing, setPlaying] = useState(false);
  const [ready,   setReady]   = useState(false);
  const [error,   setError]   = useState(false);

  // Build audio object whenever base64 changes
  useEffect(() => {
    if (!base64wav) return;

    // Clean up previous audio
    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current.src = '';
    }

    setPlaying(false);
    setReady(false);
    setError(false);

    const audio = new Audio(`data:audio/wav;base64,${base64wav}`);
    audioRef.current = audio;

    audio.oncanplaythrough = () => setReady(true);
    audio.onplay           = () => setPlaying(true);
    audio.onpause          = () => setPlaying(false);
    audio.onended          = () => { setPlaying(false); };
    audio.onerror          = () => { setError(true); setPlaying(false); };

    audio.load();

    // Attempt autoplay after 300ms delay
    // The user just pressed Send — that counts as a gesture in most browsers.
    // The delay lets React finish rendering first.
    if (autoPlay) {
      const timer = setTimeout(() => {
        audio.play().catch(() => {
          // Browser blocked it — play button is visible, user can click
        });
      }, 300);
      return () => {
        clearTimeout(timer);
        audio.pause();
        audio.src = '';
      };
    }

    return () => {
      audio.pause();
      audio.src = '';
    };
  }, [base64wav]); // only dep is the audio data itself

  const toggle = useCallback(() => {
    const audio = audioRef.current;
    if (!audio) return;
    if (playing) {
      audio.pause();
    } else {
      audio.play().catch(() => {});
    }
  }, [playing]);

  if (!base64wav) return null;
  if (error)      return null; // silent fail on error — don't break chat UI

  return (
    <button
      onClick={toggle}
      aria-label={playing ? 'Pause audio response' : 'Play audio response'}
      style={{
        display:      'inline-flex',
        alignItems:   'center',
        gap:          '6px',
        marginTop:    '10px',
        padding:      '5px 12px',
        borderRadius: '99px',
        border:       `1px solid ${playing ? 'var(--border-accent)' : 'var(--border)'}`,
        background:   playing ? 'rgba(196,181,253,0.12)' : 'var(--bg-elevated)',
        cursor:       'pointer',
        transition:   'all 150ms',
      }}
    >
      {playing
        ? <Pause  size={13} color="#C4B5FD" />
        : <Play   size={13} color="var(--text-secondary)" />
      }
      <span style={{
        fontSize:   '12px',
        fontWeight: 500,
        color:      playing ? '#C4B5FD' : 'var(--text-secondary)',
        fontFamily: 'var(--font-ui)',
      }}>
        {playing ? 'Playing…' : 'Play response'}
      </span>
      {playing && (
        // Animated sound wave bars
        <span style={{ display: 'flex', alignItems: 'center', gap: '2px' }}>
          {[1,2,3].map(i => (
            <span key={i} style={{
              display:         'inline-block',
              width:           '2px',
              background:      '#C4B5FD',
              borderRadius:    '1px',
              animation:       `soundwave 0.8s ease-in-out ${i * 0.15}s infinite alternate`,
              height:          `${6 + i * 3}px`,
            }} />
          ))}
        </span>
      )}
    </button>
  );
}
